from __future__ import annotationsimport typingimport commands2import wpilibfrom commands2 import RunCommandfrom commands2.button import CommandGenericHIDfrom wpilib import XboxControllerfrom commands.approach import ApproachTagfrom commands.reset_xy import ResetXY, ResetSwerveFrontfrom commands.setcamerapipeline import SetCameraPipelinefrom commands.swervetopoint import SwerveMovefrom constants import OIConstantsfrom subsystems.drivesubsystem import DriveSubsystem, BadSimPhysicsfrom subsystems.limelight_camera import LimelightCameraclass RobotContainer:    """    This class is where the bulk of the robot should be declared. Since Command-based is a    "declarative" paradigm, very little robot logic should actually be handled in the :class:`.Robot`    periodic methods (other than the scheduler calls). Instead, the structure of the robot (including    subsystems, commands, and button mappings) should be declared here.    """    def __init__(self, robot) -> None:        # The robot's subsystems        self.robotDrive = DriveSubsystem()        if commands2.TimedCommandRobot.isSimulation():            self.robotDrive.simPhysics = BadSimPhysics(self.robotDrive, robot)        self.frontLimelight = LimelightCamera("limelight")        self.frontLimelight.setPiPMode(2)        # The driver's controller        self.driverController = CommandGenericHID(OIConstants.kDriverControllerPort)        self.operatorController = CommandGenericHID(OIConstants.kOperatorControllerPort)        # Configure the button bindings and autos        self.configureButtonBindings()        self.configureAutos()        # Configure default command for driving using sticks        from commands.holonomicdrive import HolonomicDrive        self.robotDrive.setDefaultCommand(            HolonomicDrive(                self.robotDrive,                forwardSpeed=lambda: self.driverController.getRawAxis(XboxController.Axis.kLeftY),                leftSpeed=lambda: self.driverController.getRawAxis(XboxController.Axis.kLeftX),                rotationSpeed=lambda: -self.driverController.getRawAxis(XboxController.Axis.kRightX),                deadband=OIConstants.kDriveDeadband,                fieldRelative=True,                rateLimit=True,                square=True,            )        )    def configureButtonBindings(self) -> None:        """        Use this method to define your button->command mappings. Buttons can be created by        instantiating a :GenericHID or one of its subclasses (Joystick or XboxController),        and then passing it to a JoystickButton.        """        def swerveSide(metersToTheLeft: float, metersBackwards: float, drivetrain: DriveSubsystem, speed=1.0,                       heading=None):            """            metersToTheLeft: How many meters you want to go to the left? Negative numbers for right.            metersBackwards: How many meters you want to go backwards? Negative numbers for forward.            drivetrain: The DriveSubsystem you'd like to use.            speed: The speed you'd like the robot to swerve at.            heading: The heading you'd like the robot to look at after swerving.            """            return SwerveMove(metersToTheLeft=metersToTheLeft, metersBackwards=metersBackwards, drivetrain=drivetrain,                              speed=speed,                              heading=heading)  # By Jonas: I had to do this because when I used SwerveMove twice        # it would return errors.        def roundHeading():            """            Returns the current heading of the robot to the nearest 60.            """            angle = self.robotDrive.getHeading().degrees()            result = 60 * round(angle / 60)            print(f"Rounded heading to {result} and angle is {angle}")            return result        # Driver Controller        povUpDriverButton = self.driverController.pov(0)        povUpDriverButton.onTrue(ResetXY(x=0.0, y=0.0, headingDegrees=0.0, drivetrain=self.robotDrive))        povUpDriverButton.whileTrue(RunCommand(self.robotDrive.setX, self.robotDrive))        povDownDriverButton = self.driverController.pov(180)        povDownDriverButton.onTrue(ResetSwerveFront(self.robotDrive))        yButtonDriver = self.driverController.button(XboxController.Button.kY)        setPipeline0 = SetCameraPipeline(camera=self.frontLimelight, pipelineIndex=0)        approachTagLeft = ApproachTag(camera=self.frontLimelight, drivetrain=self.robotDrive, speed=1.0,                                          pushForwardSeconds=None,                                          specificHeadingDegrees=roundHeading)        swerveMiddle = swerveSide(metersToTheLeft=0.2, metersBackwards=0.0, drivetrain=self.robotDrive, speed=0.5)        yButtonDriver.whileTrue(setPipeline0.andThen(approachTagLeft).andThen(swerveMiddle))        leftDriverBumper = self.driverController.button(XboxController.Button.kLeftBumper)        setPipeline0 = SetCameraPipeline(camera=self.frontLimelight, pipelineIndex=0)        approachTagLeft = ApproachTag(camera=self.frontLimelight, drivetrain=self.robotDrive, speed=1.0,                                      pushForwardSeconds=None,                                      specificHeadingDegrees=roundHeading)        swerveToLeft = swerveSide(metersToTheLeft=0.32 , metersBackwards=0.0, drivetrain=self.robotDrive, speed=0.5)        leftDriverBumper.whileTrue(setPipeline0.andThen(approachTagLeft).andThen(swerveToLeft))        rightDriverBumper = self.driverController.button(XboxController.Button.kRightBumper)        setPipeline0 = SetCameraPipeline(camera=self.frontLimelight, pipelineIndex=0)        approachTagRight = ApproachTag(camera=self.frontLimelight, drivetrain=self.robotDrive, speed=1.0,                                       pushForwardSeconds=None,                                       specificHeadingDegrees=roundHeading)        swerveToRight = swerveSide(metersToTheLeft=-0.0288, metersBackwards=0.0, drivetrain=self.robotDrive, speed=0.5)        rightDriverBumper.whileTrue(setPipeline0.andThen(approachTagRight).andThen(swerveToRight))    def disablePIDSubsystems(self) -> None:        """Disables all ProfiledPIDSubsystem and PIDSubsystem instances.        This should be called on robot disable to prevent integral windup."""    def getAutonomousCommand(self) -> commands2.Command:        """        :returns: the command to run in autonomous        """        command = self.chosenAuto.getSelected()        return command()    def configureAutos(self):        self.chosenAuto = wpilib.SendableChooser()    def getTestCommand(self) -> typing.Optional[commands2.Command]:        """        :returns: the command to run in test mode (to exercise all systems)        """        return None